import{_ as e,o as a,c as r,a3 as o}from"./chunks/framework.BLaSdaBb.js";const s="/screens/main-menu.png",n="/screens/tutorial.png",i="/screens/class-pick.png",l="/screens/chamber.png",h="/screens/guild-confirm.png",w=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md"}'),d={name:"getting-started.md"};function g(u,t,p,c,m,y){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><h2 id="installing" tabindex="-1">Installing <a class="header-anchor" href="#installing" aria-label="Permalink to &quot;Installing&quot;">​</a></h2><p><strong>Play in the browser</strong>: the latest release is hosted at <a href="https://play.athanor.games/" target="_blank" rel="noreferrer">play.athanor.games</a> (best in a landscape window). It is free and ad-supported: the ads sit in bands above and below the page, outside the game entirely, never over it. The settings menu has a <strong>Fullscreen</strong> switch.</p><p>Or grab the latest <strong>Android APK</strong> from the <a href="/download.html">download page</a>. Take the <code>arm64-v8a</code> build unless you know otherwise, then open it: your browser will offer to install it, and you may need to allow installs from that source. The game plays in landscape.</p><h2 id="starting-a-campaign" tabindex="-1">Starting a campaign <a class="header-anchor" href="#starting-a-campaign" aria-label="Permalink to &quot;Starting a campaign&quot;">​</a></h2><p><img src="'+s+'" alt="Main menu"></p><p><em>New Game starts a fresh campaign, Custom World lets you pick the seed, Continue resumes your last save, and Settings controls sound and display.</em></p><p>The game opens on a short intro cinematic. Tap <strong>Skip ▸</strong> any time to jump straight to the menu, or let it play out and the menu arrives on its final frame.</p><p>From the main menu choose <strong>New Game</strong>, or <strong>Custom World</strong> to pick the world seed (the same seed always forges the same world). <strong>Continue</strong> lights up once you have a campaign saved, and <strong>Settings</strong> opens the sound and play options.</p><h3 id="a-guided-first-turn" tabindex="-1">A guided first turn <a class="header-anchor" href="#a-guided-first-turn" aria-label="Permalink to &quot;A guided first turn&quot;">​</a></h3><p><img src="'+n+'" alt="The guided first turn"></p><p><em>The screen dims to highlight what&#39;s important, with a note explaining what to tap and why. You can skip any step.</em></p><p>Your first campaign walks you through the opening: the screen dims to the one thing to tap next, with a note on why. It covers taking command, raising a soldier, putting your city to work, beginning a study, settling a field, and taking your Grand Athanor back. Every card carries a <strong>Skip tutorial</strong> button.</p><p>It never appears twice, never interrupts a saved game you resume, and never shows up at all once you have won a campaign. <strong>Settings</strong> can switch it back on, or start the whole tour again.</p><h3 id="_1-choose-your-lord-s-calling" tabindex="-1">1. Choose your Lord&#39;s calling <a class="header-anchor" href="#_1-choose-your-lord-s-calling" aria-label="Permalink to &quot;1. Choose your Lord&#39;s calling&quot;">​</a></h3><p><img src="'+i+'" alt="Choosing a class"></p><p><em>Pick your Lord&#39;s calling. Each plays completely differently in combat and affects your starting treasury and research priority.</em></p><p>Your Lord is the guild: if they fall, the campaign is lost. Each calling plays differently:</p><ul><li><strong>Warrior</strong>: front-line steel. <em>Rally</em>, the art they study first, hardens the whole party.</li><li><strong>Alchemist</strong>: fragile, but opens battles with a devastating <em>Transmute Blast</em> of raw Essence.</li><li><strong>Rogue</strong>: fastest on the road, deadliest from ambush, and the only calling that can <em>sneak</em> parties through dungeon floors.</li></ul><h3 id="_2-choose-your-guild" tabindex="-1">2. Choose your guild <a class="header-anchor" href="#_2-choose-your-guild" aria-label="Permalink to &quot;2. Choose your guild&quot;">​</a></h3><p><img src="'+l+'" alt="The chamber of eight"></p><p><em>Seven seats around the ring (the guilds), Entropy at the center. Tap a seat to see its perks, terrain, and starting stats. The same layout mirrors the world map itself.</em></p><p>Seven seats ring the chamber floor, and Entropy holds the middle. The world has the same shape: the rot at the heart, everyone else around it. Tap a seat to see that guild&#39;s details: its special ability, home terrain, rival guild, story, and your starting Lord stats. Tap another seat to switch guilds, or tap the ✕ to close the panel.</p><p>Every guild has a distinct perk. Sulfur&#39;s blades hit harder, Aether marches faster, Aurum&#39;s vaults run deeper, Salt&#39;s shield walls hold.</p><h3 id="_3-lore-stats-and-go" tabindex="-1">3. Lore, stats, and go <a class="header-anchor" href="#_3-lore-stats-and-go" aria-label="Permalink to &quot;3. Lore, stats, and go&quot;">​</a></h3><p><img src="'+h+'" alt="Confirming your guild"></p><p><em>Review your choices: starting stats, first skill, treasury, story, and what the campaign will demand of you. You can go back and change guilds before pressing Choose.</em></p><p>The last screen lays out what you are committing to: your Lord&#39;s exact starting stats, the art their calling studies first, what the treasury opens with, the guild&#39;s story and ground, and what the campaign is going to ask of you. Press <strong>Choose</strong> and it begins.</p><p>Your first campaign runs at the gentlest setting. There is no difficulty to weigh before you know what any of it means. Finish the Great Work once and the choice appears here; finish it on Hard and Entropy itself becomes playable. See <a href="/guide/settings.html">Settings &amp; Unlocks</a>.</p><h2 id="your-first-days" tabindex="-1">Your first days <a class="header-anchor" href="#your-first-days" aria-label="Permalink to &quot;Your first days&quot;">​</a></h2><p>You start with your Lord and two followers in your capital city. Your own <strong>Grand Athanor</strong> stands nearby, held by the Faithless Marauders. Liberating it is your first quest, and it pays: renown for your Lord, followers and infamy for your guild, and its income and territory afterward.</p><h3 id="🎯-the-goal" tabindex="-1">🎯 The Goal <a class="header-anchor" href="#🎯-the-goal" aria-label="Permalink to &quot;🎯 The Goal&quot;">​</a></h3><p><strong>Capture Entropy&#39;s Grand Athanor</strong> (at the world&#39;s center) to complete the Great Work and win the campaign. It is the only way to truly end the blight. Defeating Entropy&#39;s heroes helps, but their central stronghold is what matters.</p><h3 id="⚠️-why-speed-matters" tabindex="-1">⚠️ Why Speed Matters <a class="header-anchor" href="#⚠️-why-speed-matters" aria-label="Permalink to &quot;⚠️ Why Speed Matters&quot;">​</a></h3><p>The blight spreads gradually outward from Entropy&#39;s heart. Every day it goes unchecked, it swallows more territory. <strong>Your controlled territory stops it in place</strong>, so capturing buildings quickly is survival, not just ambition. The gentler outer ring is safe to learn in, but don&#39;t wait too long before pushing toward the center.</p><h3 id="💡-core-loop-what-to-do-each-day" tabindex="-1">💡 Core Loop: What to Do Each Day <a class="header-anchor" href="#💡-core-loop-what-to-do-each-day" aria-label="Permalink to &quot;💡 Core Loop: What to Do Each Day&quot;">​</a></h3><ol><li><strong>Move your armies</strong>: attack enemy buildings, defend your own, or explore</li><li><strong>Manage cities</strong>: recruit new soldiers, research skills, build farms</li><li><strong>Pay your army</strong>: each soldier costs upkeep; see the treasury at day&#39;s end</li><li><strong>End Day</strong>: everyone refreshes, a new day begins</li></ol><p>Repeat until you hold Entropy&#39;s Grand Athanor.</p><h3 id="from-here" tabindex="-1">From Here <a class="header-anchor" href="#from-here" aria-label="Permalink to &quot;From Here&quot;">​</a></h3><p>The tutorial walks you through liberating your own Grand Athanor and your first few turns. Win once, and the difficulty options open up on your next campaign. See <a href="/guide/settings.html">Settings &amp; Unlocks</a> for what else you can unlock.</p>',40)])])}const b=e(d,[["render",g]]);export{w as __pageData,b as default};
